/** 提供数值计算示例。 */
public class Sample {
 /** 创建计算器。 */ public Sample() {}
 /** 输出结果的初始值。 */ public int value;
 /** 返回输入数值。
  * @param input 待返回的输入数值
  * @return {@code input} 的原值
  * @throws IllegalArgumentException 输入为负数时抛出
  */
 public int run(int input) throws IllegalArgumentException { if (input < 0) { throw new IllegalArgumentException(); } return input; }
 /** {@inheritDoc} */
 @Override public String toString() { return "sample"; }
}
